  "style_tags": ["时尚大片", "夜间森林摄影", "面料细节", "复古胶片美学"],
  "technical": {
    "aspect_ratio": "3:4",
    "lighting": "[月光轮廓光]",
    "camera": "35mm胶片人像"
  }
}

